'use client';

import { useState, useEffect } from 'react';
import Navigation from '@/components/Navigation';
import LoadingScreen from '@/components/LoadingScreen';
import LandingPage from '@/components/sections/LandingPage';
import MeSection from '@/components/sections/Me';
import SummersSection from '@/components/sections/Summers';
import ProjectsSection from '@/components/sections/Projects';
import ExperienceSection from '@/components/sections/Experience';
import FashionSection from '@/components/sections/Fashion';
import ContactSection from '@/components/sections/Contact';

export default function Home() {
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    // Simulate loading time - remove or adjust based on your needs
    const timer = setTimeout(() => {
      setIsLoading(false);
    }, 2000);

    return () => clearTimeout(timer);
  }, []);

  if (isLoading) {
    return <LoadingScreen />;
  }

  return (
    <main className="w-full">
      <Navigation />
      <LandingPage />
      <MeSection />
      <SummersSection />
      <ProjectsSection />
      <ExperienceSection />
      <FashionSection />
      <ContactSection />
    </main>
  );
}
